#pragma once
#include <utility>
#include <string>
#include <iostream>
#include "Common.h"

class InvalidAccess : public std::exception {
public:
    explicit InvalidAccess(const char* msg) : _msg(msg) {}
    const char* what() const noexcept override { return _msg; }
private:
    const char* _msg;
};

enum class InstructionType {
    R, I, S, B, U, J
};

using Instruction = unsigned int;
using Immediate = int;

struct InstructionBase {
    uint8_t opcode : 7;
    uint8_t rs1 : 5;
    uint8_t rd : 5;
    uint8_t funct3 : 3;
    uint8_t funct7 : 7;
    Immediate imm;
    Instruction inst;
    InstructionType t;

    InstructionBase() = default;
    explicit InstructionBase(Instruction i) : inst(i), t(InstructionType::R) {
        opcode = get_digits(inst, 6, 0);
        rd     = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        rs1    = get_digits(inst, 19, 15);
        rs2    = get_digits(inst, 24, 20);
        funct7 = get_digits(inst, 31, 25);
    }

    bool is_nop() const {
        return inst == 0;
    }

    static uint32_t bin_mask(int digits) {
        return (digits < 0 || digits > 32) ? 0 : ((1u << digits) - 1);
    }

    static uint8_t get_digits(Instruction i, int hi, int lo) {
        const auto mask = bin_mask(hi - lo + 1);
        return (i >> lo) & mask;
    }

    Immediate expand_digit(uint8_t digit, int lo) {
        if ((digit >> (lo)) & 1) {
            return static_cast<Immediate>(digit | (~bin_mask(lo + 1)));
        }
        return static_cast<Immediate>(digit);
    }

    bool is_valid(const std::string& key) const {
        switch (t) {
            case InstructionType::R: return true;
            case InstructionType::I: return key != "rs2" && key != "funct7";
            case InstructionType::S: return key != "rd";
            case InstructionType::B: return key == "opcode" || key == "funct3" || key == "rs1" || key == "rs2";
            case InstructionType::U: return key == "opcode" || key == "rd";
            case InstructionType::J: return true;
        }
        return false;
    }

    void verify(const std::string& key) const {
        if (!is_valid(key)) throw InvalidAccess("Invalid field access for instruction type");
    }

    void debug() const {
        switch (opcode) {
            case 0b0110111: std::cout << "LUI rd=" << static_cast<int>(rd) << ", imm=" << imm; break;
            case 0b0010111: std::cout << "AUIPC rd=" << static_cast<int>(rd) << ", imm=" << imm; break;
            case 0b1101111: std::cout << "JAL rd=" << static_cast<int>(rd) << ", imm=" << imm; break;
            case 0b1100111: std::cout << "JALR rd=" << static_cast<int>(rd) << ", rs1=" << static_cast<int>(rs1); break;
            default: std::cout << "Unknown opcode=" << static_cast<int>(opcode);
        }
    }

    bool has_op1() const { return t != InstructionType::U; }
    bool has_op2() const { return t == InstructionType::R || t == InstructionType::S || t == InstructionType::B;
    }
};

struct InstructionR : public InstructionBase {
    explicit InstructionR(Instruction i) : InstructionBase(i) {
        opcode = get_digits(inst, 6, 0);
        rd     = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        rs1    = get_digits(inst, 19, 15);
        rs2    = get_digits(inst, 24, 20);
        funct7 = get_digits(inst, 31, 25);
        t      = InstructionType::R;
    }
};

struct InstructionI : public InstructionBase {
    explicit InstructionI(Instruction i) : InstructionBase(i) {
        opcode = get_digits(inst, 6, 0);
        rd     = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        rs1    = get_digits(inst, 19, 15);
        imm    = expand_digit(get_digits(inst, 30, 20), 11);
        t      = InstructionType::I;
    }
};

struct InstructionS : public InstructionBase {
    explicit InstructionS(Instruction i) : InstructionBase(i) {
        opcode = get_digits(inst, 6, 0);
        funct3 = get_digits(inst, 14, 12);
        rs1    = get_digits(inst, 19, 15);
        rs2    = get_digits(inst, 24, 20);
        imm    = expand_digit((get_digits(inst, 30, 25) << 5) | get_digits(inst, 11, 7), 11);
        t      = InstructionType::S;
    }
};

struct InstructionB : public InstructionBase {
    explicit InstructionB(Instruction i) : InstructionBase(i) {
        opcode = get_digits(inst, 6, 0);
        funct3 = get_digits(inst, 14, 12);
        rs1    = get_digits(inst, 19, 15);
        rs2    = get_digits(inst, 24, 20);
        imm    = expand_digit((get_digits(inst, 30, 25) << 5) | (get_digits(inst, 7, 7) << 11) | get_digits(inst, 11, 8), 12);
        t      = InstructionType::B;
    }
};

struct InstructionU : public InstructionBase {
    explicit InstructionU(Instruction i) : InstructionBase(i) {
        opcode = get_digits(inst, 6, 0);
        rd     = get_digits(inst, 11, 7);
        imm    = expand_digit((get_digits(inst, 30, 20) << 12) | (get_digits(inst, 19, 12) << 0), 31);
        t      = InstructionType::U;
    }
};

struct InstructionJ : public InstructionBase {
    explicit InstructionJ(Instruction i) : InstructionBase(i) {
        opcode = get_digits(inst, 6, 0);
        rd     = get_digits(inst, 11, 7);
        imm    = expand_digit((get_digits(inst, 30, 21) << 11) | (get_digits(inst, 20, 20) << 10) | (get_digits(inst, 19, 12) << 0), 20);
        t      = InstructionType::J;
    }
};
